import{_ as a,o as i,c as t,a5 as o}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Ambientes de execução de plugins e limites de confiança","description":"","frontmatter":{"title":"Ambientes de execução de plugins e limites de confiança","docId":"developer.plugins.runtimes","translationKey":"developer.plugins.runtimes","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a249fa36fa53f3bfe7da57fdd25a445e593517946f80ac7e891b54d95cdc17d","translationRevision":"1b8cf741b008d38404fbf91d5c8b0295f0628f0b2e68c477ee94761e16e198c7","order":260},"headers":[],"relativePath":"pt/developer/plugins/runtimes.md","filePath":"pt/developer/plugins/runtimes.md","lastUpdated":1794611623000}'),s={name:"pt/developer/plugins/runtimes.md"};function d(n,e,r,l,c,p){return i(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="plugin-runtimes-and-trust-limits" tabindex="-1">Ambientes de execução de plugins e limites de confiança <a class="header-anchor" href="#plugin-runtimes-and-trust-limits" aria-label="Permalink to &quot;Ambientes de execução de plugins e limites de confiança {#plugin-runtimes-and-trust-limits}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Selecione um formato executável cujas dependências e confiança correspondam ao host. Leia a <a href="./">visão geral dos plugins</a>, valide o manifesto em relação à compilação real e inspecione restrições específicas do destino antes de carregar código. Compatibilidade de protocolo, compatibilidade de ABI nativa e concessões de permissão são verificações independentes.</p><h2 id="choose-an-implemented-runtime" tabindex="-1">Escolha um ambiente implementado <a class="header-anchor" href="#choose-an-implemented-runtime" aria-label="Permalink to &quot;Escolha um ambiente implementado {#choose-an-implemented-runtime}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Runtime</th><th>Execução</th><th>Confiança e portabilidade</th></tr></thead><tbody><tr><td><code>native</code></td><td>ABI C com <code>libloading</code></td><td>Código confiável no mesmo processo; específico do destino</td></tr><tr><td><code>process</code></td><td>Executável independente, stdin/stdout enquadrados</td><td>Isolamento de falhas, permissões comuns do usuário no sistema</td></tr><tr><td><code>napi-vm</code></td><td>JS compilado antecipadamente no QuickJS via <code>rquickjs</code></td><td>Efeitos do host negados por padrão; addons nativos opcionais alteram a confiança</td></tr><tr><td><code>declarative</code></td><td>Descritores de integração validados</td><td>Sem programa convidado; efeitos usam o broker do host</td></tr><tr><td><code>wasm</code></td><td>Opção de runtime opcional</td><td>Mecanismo geral não habilitado nas compilações normais</td></tr></tbody></table><p>A ABI nativa v1 troca bytes serializados por uma pequena tabela C; contêineres Rust, objetos trait e futures não a atravessam. Bibliotecas nativas permanecem carregadas até o encerramento. O enquadramento de processo usa comprimento u32 little-endian seguido de bytes JSON, não RPC de controle delimitado por linhas. Mantenha a saída de diagnóstico fora do canal stdout enquadrado.</p><h2 id="understand-quickjs-compatibility" tabindex="-1">Entenda a compatibilidade QuickJS <a class="header-anchor" href="#understand-quickjs-compatibility" aria-label="Permalink to &quot;Entenda a compatibilidade QuickJS {#understand-quickjs-compatibility}&quot;">​</a></h2><p>O nome de manifesto <code>napi-vm</code> permanece estável, mas afirmações antigas sobre um interpretador separado puramente Rust são históricas. Plugins recebem as variáveis globais de compatibilidade documentadas, não um ambiente Node completo. <code>napi_get_uv_event_loop</code> não é compatível. Addons nativos <code>.node</code> usam um caminho no mesmo processo deliberadamente confiável, permitido por lista e verificado por SHA-256; o nome do runtime JavaScript não os torna seguros.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-loader</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span></code></pre></div><p>Use testes específicos do carregador quando uma configuração completa de addon nativo exigir ferramentas de plataforma indisponíveis.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>A análise do manifesto rejeita combinações incompatíveis de protocolo/ABI antes do carregamento. Android permite QuickJS portátil e entradas válidas de processo Android/Bionic, mas rejeita bibliotecas dinâmicas nativas e addons <code>.node</code>. Um artefato Linux/glibc de desktop não é um plugin de processo Android.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Reinicie um host privado após substituir uma biblioteca nativa. Se a inicialização exceder o tempo limite e ficar incerta, o gerenciador pode manter a identidade do worker e bloquear a substituição; não contorne esse estado declarando sucesso no encerramento. Buffers de eventos são limitados e a entrega pode informar atraso; emissão na inicialização não é uma fila durável. A <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-loader/src" target="_blank" rel="noreferrer">implementação do carregador</a> define o mecanismo atual e o comportamento de ciclo de vida.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Os limites atuais são memória QuickJS 512 MiB, pilha 2 MiB, orçamento de interrupção por chamada, quadros 16 MiB e até 128 chamadas enfileiradas por instância. Não garantem cancelamento de efeitos. Um processo com timeout é terminado/removido; uma chamada nativa não pode ser morta com segurança e a instância é mantida. Efeitos no SO podem já ter ocorrido. Confira resultado original e ciclo de vida antes de substituir/repetir. Addons <code>.node</code> confiáveis usam privilégios do host fora do limite JS.</p>`,16)])])}const h=a(s,[["render",d]]);export{u as __pageData,h as default};
